using System;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public class CombatRailArtilleryTests {
 [Test] public void TamperedArtilleryFieldsAndFakeInflightAreRejected(){var a=New();Call(a,"Advance",1L,2,0L,false);Call(a,"Advance",11L,2,100L,false);var good=State(a);foreach(string kind in new[]{"missing-hp","negative-launch","passed-too-soon","waiting-late","fake-shot"}){var bad=(JObject)good.DeepClone();var row=(JObject)bad["encounters"][0];if(kind=="missing-hp")row.Remove("hp");if(kind=="negative-launch")row["nextLaunch"]=-1;if(kind=="passed-too-soon")row["status"]="Passed";if(kind=="waiting-late")row["status"]="Waiting";if(kind=="fake-shot"){var shot=bad["projectiles"][0].DeepClone();shot["sequence"]=2;((JArray)bad["projectiles"]).Add(shot);bad["sequence"]=2;}Assert.Throws<ArgumentException>(()=>Call(New(),"Restore",bad),kind);}}
 public static JObject Config()=>JObject.Parse(@"{'version':'rail-artillery-v1','stepMs':50,'definition':{'id':'rail_artillery_emplacement_v1','maxHp':1000,'trainDamage':50,'periodMs':2000,'windupMs':500,'projectileTravelMs':500},'encounters':[{'id':'gun-2','spawnWave':2,'definitionId':'rail_artillery_emplacement_v1','exposureDistanceMm':120000}],'policy':{'requiredForWaveCompletion':false,'passedKillCount':0,'destroyedKillCount':1,'reward':'NONE','onExit':'CANCEL_UNLAUNCHED_KEEP_IN_FLIGHT','sameTickOrder':'DAMAGE_EXIT_THEN_LAUNCH_THEN_IMPACT'}}");
 static object New(){var t=typeof(BasicCombatSimulation).Assembly.GetType("LastRail.Battle.CombatRailArtillery");Assert.NotNull(t);return Activator.CreateInstance(t,new object[]{Config()});}
 static object Call(object target,string name,params object[] args){try{return target.GetType().GetMethod(name).Invoke(target,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static JObject State(object a)=>(JObject)Call(a,"Capture");
 [Test] public void ExitBeforeLaunchCancelsButLaunchedProjectileSurvivesSource(){var a=New();Call(a,"Advance",1L,2,0L,false);Call(a,"Damage","gun-2",1000);Call(a,"Advance",11L,2,0L,false);Assert.AreEqual("Destroyed",(string)State(a)["encounters"][0]["status"]);Assert.AreEqual(0,((JArray)State(a)["projectiles"]).Count);var b=New();Call(b,"Advance",1L,2,0L,false);Call(b,"Advance",11L,2,0L,false);Call(b,"Damage","gun-2",1000);Call(b,"Advance",12L,3,0L,false);var impacts=(JArray)Call(b,"Advance",21L,3,0L,true);Assert.AreEqual(1,impacts.Count);Assert.AreEqual(50,(int)impacts[0]["damage"]);Assert.AreEqual(0,((JArray)State(b)["projectiles"]).Count);}
 [Test] public void DistanceExitHasNoKillAndChangingWaveDoesNotRemoveEncounter(){var a=New();Call(a,"Advance",1L,2,100L,false);Call(a,"Advance",2L,3,1000L,false);Assert.AreEqual("Active",(string)State(a)["encounters"][0]["status"]);Call(a,"Advance",11L,3,120100L,false);Assert.AreEqual("Passed",(string)State(a)["encounters"][0]["status"]);Assert.AreEqual(0,(int)State(a)["destroyedCount"]);Assert.AreEqual(0,((JArray)State(a)["projectiles"]).Count);}
 [Test] public void PendingProjectileRoundTripsAndTerminalStopsNewLaunches(){var a=New();Call(a,"Advance",1L,2,0L,false);Call(a,"Advance",11L,2,0L,false);var snapshot=State(a);var b=New();Call(b,"Restore",snapshot);Assert.IsTrue(JToken.DeepEquals(snapshot,State(b)));Assert.AreEqual(1,((JArray)Call(b,"Advance",21L,2,0L,true)).Count);Call(b,"Advance",100L,2,0L,true);Assert.AreEqual(0,((JArray)State(b)["projectiles"]).Count);}
}
